const costIds=['buy','km','use','fuel','visits','service','parts','fees','extras'];
const costNames={buy:'سعر الشراء',km:'المسافة',use:'الاستهلاك',fuel:'سعر الوقود',visits:'عدد الزيارات',service:'تكلفة الزيارة',parts:'القطع',fees:'الرسوم',extras:'الإضافات'};
function calculate(){
 const v={},missing=[],invalid=[];
 for(const id of costIds){const el=$('#c-'+id);if(el.value===''){missing.push(costNames[id]);v[id]=null;el.removeAttribute('aria-invalid')}else{v[id]=Number(el.value);if(!Number.isFinite(v[id])||v[id]<0||(['visits','km'].includes(id)&&!Number.isInteger(v[id]))){invalid.push(costNames[id]);el.setAttribute('aria-invalid','true')}else el.removeAttribute('aria-invalid')}}
 const complete=ids=>!invalid.length&&ids.every(id=>v[id]!==null);
 const annualReady=complete(['km','use','fuel','visits','service','parts','fees']);
 let annual=annualReady?v.km/100*v.use*v.fuel+v.visits*v.service+v.parts+v.fees:null;
 const overflow=annual!==null&&(!Number.isFinite(annual)||!Number.isFinite(annual+(v.buy||0)+(v.extras||0)));
 if(overflow)annual=null;
 $('#calcAnnual').innerHTML=annual===null?'غير مكتمل':money(annual);
 $('#calcFirst').innerHTML=annual!==null&&complete(['buy','extras'])?money(annual+v.buy+v.extras):'غير مكتمل';
 $('#calcBreak').textContent=annual!==null?`وقود ${nf.format(v.km/100*v.use*v.fuel)} + زيارات ${nf.format(v.visits*v.service)} + قطع ${nf.format(v.parts)} + رسوم ${nf.format(v.fees)} ج.م`:'أكمل مدخلات التشغيل لحساب الإجمالي.';
 $('#calcPer').textContent=annual!==null&&v.km>0?`تكلفة الكيلومتر التشغيلية: ${nf.format(annual/v.km)} ج.م`:'';
 $('#calcMissing').textContent=overflow?'الأرقام أكبر من نطاق الحساب. راجع المدخلات.':invalid.length?'قيم غير صالحة: '+invalid.join('، ')+'. استخدم أرقامًا غير سالبة وعدد زيارات ومسافة صحيحين.':missing.length?'غير محدد: '+missing.join('، ')+'.':'كل المدخلات مكتملة؛ الناتج تقدير على أرقامك وليس عرض سعر.';
}
$('#costform').addEventListener('submit',e=>{e.preventDefault();calculate()});
$('#costform').addEventListener('input',calculate);$('#costform').addEventListener('reset',()=>setTimeout(calculate,0));calculate();
function download(content,filename,type){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([content],{type}));a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000)}
$('#downloadall').addEventListener('click',()=>download(DATA.fullCSV,'scooter-parts-egypt.csv','text/csv;charset=utf-8'));
$('#downloadreport').addEventListener('click',()=>download(DATA.report,'scooter-comparison-research-ar.md','text/markdown;charset=utf-8'));
let catalog=[],filtered=[],catPage=0,loading=false,loaded=false;const pageSize=12;
const normalize=s=>String(s??'').toLowerCase().normalize('NFKD').replace(/[\u064b-\u065f\u0670\u0640]/g,'').replace(/[أإآ]/g,'ا').replace(/ى/g,'ي').replace(/[٠-٩۰-۹]/g,c=>String(c.charCodeAt(0)-(c<='٩'?1632:1776)));
function applyFilters(){
 const terms=normalize($('#q').value.trim()).split(/\s+/).filter(Boolean),model=$('#modelFilter').value,category=$('#catFilter').value,status=$('#statusFilter').value,sort=$('#sortFilter').value;
 filtered=catalog.filter(r=>(!model||r.modelId===model)&&(!category||r.category===category)&&terms.every(t=>normalize([r.name,r.externalCode,r.internalCode,r.model,r.category].join(' ')).includes(t))&&(!status||status==='priced'&&r.price!==null||status==='missing'&&r.price===null||status==='paired'&&Boolean(r.condition)));
 if(sort==='asc'||sort==='desc')filtered.sort((a,b)=>a.price===null?b.price===null?0:1:b.price===null?-1:sort==='asc'?a.price-b.price:b.price-a.price);
 if(sort==='name')filtered.sort((a,b)=>a.name.localeCompare(b.name,'ar'));catPage=0;renderCatalog();
}
function renderCatalog(){
 $('#catalogCount').textContent=`${nf.format(filtered.length)} نتيجة من ${nf.format(catalog.length)} صفًا`;
 const max=Math.max(1,Math.ceil(filtered.length/pageSize));catPage=Math.max(0,Math.min(catPage,max-1));
 $('#catalogPage').textContent=`${catPage+1} / ${max}`;$('#catPrev').disabled=catPage===0;$('#catNext').disabled=catPage>=max-1;$('#downloadfiltered').disabled=!filtered.length;
 $('#catalogRows').innerHTML=filtered.length?filtered.slice(catPage*pageSize,(catPage+1)*pageSize).map(r=>`<article class="catalogrow"><div><h4>${esc(r.name)}${r.condition?'<span class="badge">طقم إلزامي</span>':''}</h4><div class="rowmeta"><span>${esc(r.model)}</span><span>${esc(r.category)}</span>${r.externalCode?`<span>خارجي <code>${esc(r.externalCode)}</code></span>`:''}${r.internalCode?`<span>داخلي <code>${esc(r.internalCode)}</code></span>`:''}</div>${r.condition?`<p class="fitment">${esc(r.condition)}</p>`:''}<p class="fitment">${esc(r.fitment)}</p></div><div><span class="${r.price===null?'unknownprice':'money'}">${r.price===null?'دون سعر منشور':money(r.price)}</span><p class="stock">${esc(r.stock)}</p></div><a class="rowlink" href="${esc(r.source)}" target="_blank" rel="noopener noreferrer">صفحة الكتالوج ↗</a></article>`).join(''):`<div class="emptystate"><h4>مفيش نتائج بالمواصفات دي.</h4><p>جرّب جزءًا من الاسم أو الكود، أو امسح الفلاتر.</p><button class="textbutton" id="emptyreset">مسح كل الفلاتر</button></div>`;
 $('#emptyreset')?.addEventListener('click',resetFilters);
}
function loadCatalog(){if(loaded)return;catalog=DATA.catalogRows.map(row=>Object.fromEntries(DATA.catalogKeys.map((key,i)=>[key,row[i]])));loaded=true;$('#catFilter').innerHTML='<option value="">كل التصنيفات</option>'+[...new Set(catalog.map(r=>r.category).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'ar')).map(c=>`<option value="${esc(c)}">${esc(c)}</option>`).join('');applyFilters()}
function resetFilters(){for(const id of ['q','modelFilter','catFilter','statusFilter'])$('#'+id).value='';$('#sortFilter').value='original';applyFilters()}
$('#resetfilters').addEventListener('click',resetFilters);
$('#q').addEventListener('input',()=>{if(loaded)applyFilters();else loadCatalog()});
['modelFilter','catFilter','statusFilter','sortFilter'].forEach(id=>$('#'+id).addEventListener('change',()=>{if(loaded)applyFilters();else loadCatalog()}));
function pageCatalog(delta){catPage+=delta;renderCatalog();$('#catalogCount').scrollIntoView({block:'start',behavior:'instant'})}
$('#catPrev').addEventListener('click',()=>pageCatalog(-1));$('#catNext').addEventListener('click',()=>pageCatalog(1));
const csvCell=v=>'"'+String(v??'').replaceAll('"','""')+'"';
$('#downloadfiltered').addEventListener('click',()=>{const keys=['model','name','category','externalCode','internalCode','price','condition','stock','fitment','source','date'];const labels=['الموديل','القطعة','التصنيف','الكود الخارجي','الكود الداخلي','السعر ج.م','شرط الطقم','حالة الطلب','التوافق','المصدر','الرصد'];download('\uFEFF'+[labels,...filtered.map(r=>keys.map(k=>r[k]))].map(row=>row.map(csvCell).join(',')).join('\r\n'),'scooter-parts-filtered.csv','text/csv;charset=utf-8')});
loadCatalog();
